[ -d "$AIDEV_SIM/releases/v0.0.1" ] && jq -n '{tagName:"v0.0.1",name:"v0.0.1",publishedAt:"2026-01-01T00:00:00+09:00",isPrerelease:false,body:""}' > "$AIDEV_SIM/releases/v0.0.1/meta.json"
