function hydrate(value: AdvancedPolicySnapshot) {
  snapshot.value = value
  form.deleteTerm = Number(value.deleteTerm || 30)
  const adminLimit = value.notebookLimits.find((item) => item.group === 'admin')?.limit ?? -1
  const userLimit = value.notebookLimits.find((item) => item.group === 'user')?.limit ?? 5
  form.adminUnlimited = adminLimit < 0
  form.userUnlimited = userLimit < 0
  form.adminLimit = adminLimit > 0 ? adminLimit : 10
  form.userLimit = userLimit > 0 ? userLimit : 5
}

async function load() {
  const ticket = policyRequest.start()
  loading.value = true
  error.value = ''
  try {
    const result = await getAdvancedPolicySnapshot()
    if (!ticket.isLatest()) return
    hydrate(result)
  } catch (reason) {
    if (!ticket.isLatest()) return
    error.value = reason instanceof Error ? reason.message : '세부 정책을 불러오지 못했습니다.'
  } finally {
    if (ticket.isLatest()) loading.value = false
  }
}

async function runSave(key: string, action: () => Promise<unknown>, message: string) {
  if (!writesEnabled.value || saving.value) return false
  saving.value = key
  try {
    await action()
    notify(message, 'success')
    await load()
    return true
  } catch (reason) {
    notify(reason instanceof Error ? reason.message : '정책을 변경하지 못했습니다.', 'error')
    return false
  } finally {
    saving.value = ''
  }
}

